// ─── File: TransferStatusTruthDemo.java ───
// Runnable demo contrasting the swallowed-exception bug (returns 200 on a
// rolled-back transfer) with the correct design where the HTTP-equivalent
// result reflects the committed PENDING->COMPLETED/FAILED state machine.

import java.math.BigDecimal;
import java.util.*;
import java.util.logging.*;

public class TransferStatusTruthDemo {
    private static final Logger log = Logger.getLogger("BankTruth");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountRepository accounts = new AccountRepository();
        TransferRepository transfers = new TransferRepository();
        TransferService service = new TransferService(accounts, transfers, log);

        BrokenTransferController broken = new BrokenTransferController(service, log);
        SafeTransferController safe = new SafeTransferController(service, transfers, log);

        log.info(() -> "=== BROKEN controller: failing transfer still returns 200 ===");
        String brokenResp = broken.transfer("SAV2001", "CUR3001", new BigDecimal("9999999"));
        log.severe(() -> "BROKEN API returned: " + brokenResp + "  <-- LIE, rollback happened");

        log.info(() -> "=== SAFE controller: successful transfer ===");
        TransferResponse ok = safe.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));
        log.info(() -> "SAFE API returned: HTTP " + ok.httpStatus() + " status=" + ok.status());

        log.info(() -> "=== SAFE controller: failing transfer returns FAILED, not 200 ===");
        TransferResponse fail = safe.transfer("SAV2001", "CUR3001", new BigDecimal("9999999"));
        log.warning(() -> "SAFE API returned: HTTP " + fail.httpStatus() + " status=" + fail.status());

        log.info(() -> "FINAL Rajesh = " + accounts.findById("SAV2001").getBalance()
                      + ", Priya = " + accounts.findById("CUR3001").getBalance());
    }
}

// ─── model/TransferStatus.java ───
enum TransferStatus { PENDING, COMPLETED, FAILED }

// ─── model/Account.java ───
class Account {
    private final String accountId; private final String holderName; private BigDecimal balance;
    Account(String id, String name, BigDecimal bal) { accountId=id; holderName=name; balance=bal; }
    String getAccountId() { return accountId; }
    BigDecimal getBalance() { return balance; }
    void debit(BigDecimal a) { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
}

// ─── model/Transfer.java ───
class Transfer {
    private final String transferId; private final String from; private final String to;
    private final BigDecimal amount; private TransferStatus status;
    Transfer(String id, String from, String to, BigDecimal amount) {
        this.transferId=id; this.from=from; this.to=to; this.amount=amount;
        this.status = TransferStatus.PENDING;
    }
    String getTransferId() { return transferId; }
    TransferStatus getStatus() { return status; }
    void markCompleted() { this.status = TransferStatus.COMPLETED; }
    void markFailed() { this.status = TransferStatus.FAILED; }
}

// ─── dto/TransferResponse.java ───
class TransferResponse {
    private final int httpStatus; private final TransferStatus status; private final String transferId;
    TransferResponse(int httpStatus, TransferStatus status, String transferId) {
        this.httpStatus=httpStatus; this.status=status; this.transferId=transferId;
    }
    int httpStatus() { return httpStatus; }
    TransferStatus status() { return status; }
}

// ─── exception/InsufficientFundsException.java ───
class InsufficientFundsException extends RuntimeException {
    InsufficientFundsException(String msg) { super(msg); }
}

// ─── repository/AccountRepository.java ───
class AccountRepository {
    private final Map<String, Account> store = new HashMap<>();
    private final Map<String, BigDecimal> snapshot = new HashMap<>();
    AccountRepository() {
        store.put("SAV2001", new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        store.put("CUR3001", new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));
    }
    Account findById(String id) { return store.get(id); }
    void begin() { snapshot.clear(); store.forEach((k,v) -> snapshot.put(k, v.getBalance())); }
    void rollback() { store.forEach((k,v) -> v.credit(snapshot.get(k).subtract(v.getBalance()))); }
}

// ─── repository/TransferRepository.java ───
class TransferRepository {
    private final Map<String, Transfer> store = new HashMap<>();
    void save(Transfer t) { store.put(t.getTransferId(), t); }
    Transfer findById(String id) { return store.get(id); }
    // Marks the money-movement transaction boundary. Account changes are the
    // ones undone on rollback; the Transfer status is driven explicitly by the
    // service (COMPLETED inside the TX, FAILED in the catch block as an audit row).
    void begin() { /* snapshot not needed: status is set explicitly by the service */ }
}

// ─── service/TransferService.java — status set to COMPLETED INSIDE the transaction ───
class TransferService {
    private final AccountRepository accounts; private final TransferRepository transfers; private final Logger log;
    private int seq = 0;
    TransferService(AccountRepository a, TransferRepository t, Logger log) { accounts=a; transfers=t; this.log=log; }

    // @Transactional in real Spring. Status COMPLETED is part of the SAME transaction,
    // so if the money movement rolls back, the status never becomes COMPLETED.
    Transfer transfer(String from, String to, BigDecimal amount) {
        String id = "TXF-" + (++seq);
        Transfer t = new Transfer(id, from, to, amount);
        transfers.save(t); // PENDING

        accounts.begin(); transfers.begin(); // simulate TX begin
        try {
            Account f = accounts.findById(from);
            Account toAcct = accounts.findById(to);
            if (f.getBalance().compareTo(amount) < 0)
                throw new InsufficientFundsException("Insufficient balance in " + from);
            f.debit(amount);
            toAcct.credit(amount);
            t.markCompleted();            // state transition inside the TX
            log.info(() -> "transfer " + id + " applied " + from + "->" + to + " Rs." + amount);
            return t;                     // COMMIT (balances + COMPLETED both durable)
        } catch (RuntimeException ex) {
            accounts.rollback();          // money movement undone
            t.markFailed();               // record the truth: FAILED (separate audit row commit)
            log.severe(() -> "transfer " + id + " ROLLED BACK: " + ex.getMessage());
            throw ex;                     // re-throw so the controller does NOT see success
        }
    }
}

// ─── controller/BrokenTransferController.java — the bug: swallow and return 200 ───
class BrokenTransferController {
    private final TransferService service; private final Logger log;
    BrokenTransferController(TransferService s, Logger log) { this.service=s; this.log=log; }
    String transfer(String from, String to, BigDecimal amount) {
        try {
            service.transfer(from, to, amount);
            return "HTTP 200 {\"status\":\"SUCCESS\"}";
        } catch (RuntimeException ex) {
            // BUG: exception swallowed, success returned even though TX rolled back
            return "HTTP 200 {\"status\":\"SUCCESS\"}";
        }
    }
}

// ─── controller/SafeTransferController.java — status reflects committed truth ───
class SafeTransferController {
    private final TransferService service; private final TransferRepository transfers; private final Logger log;
    SafeTransferController(TransferService s, TransferRepository t, Logger log) { service=s; transfers=t; this.log=log; }

    TransferResponse transfer(String from, String to, BigDecimal amount) {
        try {
            Transfer t = service.transfer(from, to, amount);
            // 200 ONLY if the committed status is COMPLETED
            if (t.getStatus() == TransferStatus.COMPLETED)
                return new TransferResponse(200, TransferStatus.COMPLETED, t.getTransferId());
            return new TransferResponse(422, t.getStatus(), t.getTransferId());
        } catch (InsufficientFundsException ex) {
            // delegated to GlobalExceptionHandler in real Spring -> HTTP 422
            return new TransferResponse(422, TransferStatus.FAILED, null);
        }
    }
}

// ─── Clean log formatter ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel().getName(), r.getMessage());
    }
}
