// ─── File: src/main/java/com/bank/truth/controller/GlobalExceptionHandler.java ───
package com.bank.truth.controller;

import org.springframework.http.*;
import org.springframework.web.bind.annotation.*;

@RestControllerAdvice
public class GlobalExceptionHandler {
    // A rolled-back transfer maps to a failure status, NEVER 200.
    @ExceptionHandler(InsufficientFundsException.class)
    public ResponseEntity<ErrorResponse> handle(InsufficientFundsException ex) {
        return ResponseEntity.status(HttpStatus.UNPROCESSABLE_ENTITY)
            .body(new ErrorResponse("TRANSFER_FAILED", ex.getMessage()));
    }
}
